import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        long A = 0, B = 1, k = 0;
        for (long i = 1; i <= n; ++i) {
            if (i == 1) {
                A = k;
                B = i;
            }
            k = (x * i) / y;
            for (int j = 0; j <= 10; ++j) {
                long candidate_k = k + j;
                long diff_x = Math.abs(x * i - y * candidate_k);
                long diff_y = Math.abs(x * (long) B - y * (long) A);
                long cost_x = diff_x * y * B;
                long cost_y = diff_y * y * i;
                if (i == 1 && j == 0) {
                    A = k;
                    B = i;
                }
                if (cost_x < cost_y) {
                    A = candidate_k;
                    B = i;
                }
            }
        }
        long divisor = gcd(A, B);
        System.out.println((A / divisor) + "/" + (B / divisor));
        sc.close();
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}
